// Package links tests — T-11 characterization (Phase 1).
//
// THE LAW: the Python characterization tests were ported FIRST; the
// golden (testdata/link_grammar.golden.json + import_corpus.txt) was
// GENERATED by running the unmodified Python reference app
// (assadigit/GitCurator @ 98f4fc7) via testdiff/goldens/dump_links.py.
// The golden's input columns drive the Go functions — the same corpus,
// byte-compared (the spec-defined "import-file grammar" differential,
// spec-core-links §Go mapping & tests). Regenerate with:
//
//	python3 testdiff/goldens/dump_links.py
//
// Ported Python suites: tests/test_core.py (TestLinks),
// tests/test_importbatch.py (TestParseImportText, TestReadImportFile,
// TestSchemeTolerantDomainLaw), tests/test_sitenote.py (TestSiteKey),
// tests/test_sealfix.py (TestSelfDomains, scrub), the pure links halves
// of tests/test_lawfix.py (the law split).
package links

import (
	"encoding/json"
	"os"
	"path/filepath"
	"reflect"
	"strings"
	"testing"
)

// ---------------------------------------------------------------------------
// The generated golden + the differential.
// ---------------------------------------------------------------------------

type lawEntry struct {
	Key     string
	Domains []string
}

type linksGolden struct {
	Schema                  int               `json:"schema"`
	LawBlockedDomains       []string          `json:"law_blocked_domains"`
	LawPlatformDomains      []string          `json:"law_platform_domains"`
	PlatformDomainsOrdered  [][]any           `json:"platform_domains_ordered"`
	PlatformTableFiles      map[string]string `json:"platform_table_files"`
	DefaultSelfDomains      []string          `json:"default_self_domains"`
	PyLower                 [][2]string       `json:"py_lower"`
	NormalizeURL            [][2]string       `json:"normalize_url"`
	NormalizeWebsiteURL     [][2]string       `json:"normalize_website_url"`
	DomainOf                [][2]string       `json:"domain_of"`
	SiteKeyOf               [][2]string       `json:"site_key_of"`
	ScrubURLToken           [][2]string       `json:"scrub_url_token"`
	ScrubURLsInText         [][2]string       `json:"scrub_urls_in_text"`
	ClassifyPlatform        [][2]string       `json:"classify_platform"`
	DomainIsBlockedLaw      [][]any           `json:"domain_is_blocked_law"`
	DomainIsBlockedPlatform [][]any           `json:"domain_is_blocked_platform"`
	DomainIsBlockedEmpty    [][]any           `json:"domain_is_blocked_empty"`
	BlockedFromConfig       [][]any           `json:"blocked_domains_from_config"`
	PlatformFromConfig      [][]any           `json:"platform_domains_from_config"`
	SelfFromConfig          [][]any           `json:"self_domains_from_config"`
	ExtractGitHubURLs       [][]any           `json:"extract_github_urls"`
	SplitLinks              [][]any           `json:"split_links"`
	MapGitHubIOURL          [][2]string       `json:"map_github_io_url"`
	ParseImportText         ImportResult      `json:"parse_import_text"`
}

func loadGolden(t *testing.T) *linksGolden {
	t.Helper()
	raw, err := os.ReadFile(filepath.Join("testdata", "link_grammar.golden.json"))
	if err != nil {
		t.Fatalf("read golden (generate with testdiff/goldens/dump_links.py): %v", err)
	}
	var g linksGolden
	if err := json.Unmarshal(raw, &g); err != nil {
		t.Fatalf("decode golden: %v", err)
	}
	return &g
}

func TestGoldenLawLists(t *testing.T) {
	g := loadGolden(t)
	if !reflect.DeepEqual(LawBlockedDomains, g.LawBlockedDomains) {
		t.Errorf("LawBlockedDomains drifted:\n go: %v\n py: %v", LawBlockedDomains, g.LawBlockedDomains)
	}
	if !reflect.DeepEqual(LawPlatformDomains, g.LawPlatformDomains) {
		t.Errorf("LawPlatformDomains drifted:\n go: %v\n py: %v", LawPlatformDomains, g.LawPlatformDomains)
	}
	if !reflect.DeepEqual(DefaultSelfDomains, g.DefaultSelfDomains) {
		t.Errorf("DefaultSelfDomains drifted: go=%v py=%v", DefaultSelfDomains, g.DefaultSelfDomains)
	}
	if len(LawBlockedDomains) != 41 {
		t.Errorf("LAW must hold 41 domains (got %d)", len(LawBlockedDomains))
	}
	if len(LawPlatformDomains) != 37 {
		t.Errorf("platform law must hold 37 domains (got %d)", len(LawPlatformDomains))
	}
	// ordered platform table: first-match-wins order is behavior
	for i, row := range g.PlatformDomainsOrdered {
		key, _ := row[0].(string)
		doms := toStrings(t, row[1])
		if i >= len(PlatformDomains) {
			t.Fatalf("PlatformDomains missing row %d (%s)", i, key)
		}
		if PlatformDomains[i].Key != key || !reflect.DeepEqual(PlatformDomains[i].Domains, doms) {
			t.Errorf("PlatformDomains[%d] drifted: go={%s %v} py={%s %v}",
				i, PlatformDomains[i].Key, PlatformDomains[i].Domains, key, doms)
		}
	}
	if !reflect.DeepEqual(PlatformTableFiles, g.PlatformTableFiles) {
		t.Errorf("PlatformTableFiles drifted: go=%v py=%v", PlatformTableFiles, g.PlatformTableFiles)
	}
}

