func TestGoldenBlockedMatrix(t *testing.T) {
	g := loadGolden(t)
	run := func(rows [][]any, list []string, name string) {
		for _, row := range rows {
			url, _ := row[0].(string)
			want, _ := row[1].(bool)
			if got := DomainIsBlocked(url, list); got != want {
				t.Errorf("%s: DomainIsBlocked(%q) = %v; want %v", name, url, got, want)
			}
		}
	}
	run(g.DomainIsBlockedLaw, LawBlockedDomains, "law")
	run(g.DomainIsBlockedPlatform, LawPlatformDomains, "platform-law")
	run(g.DomainIsBlockedEmpty, nil, "empty-list")
}

func TestGoldenConfigProbes(t *testing.T) {
	g := loadGolden(t)
	cases := []struct {
		rows [][]any
		goFn func(map[string]any) []string
		name string
	}{
		{g.BlockedFromConfig, BlockedDomainsFromConfig, "BlockedDomainsFromConfig"},
		{g.PlatformFromConfig, PlatformDomainsFromConfig, "PlatformDomainsFromConfig"},
		{g.SelfFromConfig, SelfDomainsFromConfig, "SelfDomainsFromConfig"},
	}
	for _, c := range cases {
		for _, row := range c.rows {
			var cfg map[string]any
			switch v := row[0].(type) {
			case string:
				if v != "None" {
					if err := json.Unmarshal([]byte(v), &cfg); err != nil {
						t.Fatalf("%s: bad probe config %q: %v", c.name, v, err)
					}
				}
			default:
				t.Fatalf("%s: probe key has type %T", c.name, row[0])
			}
			want := toStrings(t, row[1])
			if got := c.goFn(cfg); !reflect.DeepEqual(got, want) {
				t.Errorf("%s(%v) = %v; want %v", c.name, row[0], got, want)
			}
		}
	}
}

func TestGoldenExtraction(t *testing.T) {
	g := loadGolden(t)
	row := g.ExtractGitHubURLs[0]
	text, _ := row[0].(string)
	wantDedupe := toStrings(t, row[1])
	wantRaw := toStrings(t, row[2])
	if got := ExtractGitHubURLs(text); !reflect.DeepEqual(got, wantDedupe) {
		t.Errorf("ExtractGitHubURLs(dedupe) = %v; want %v", got, wantDedupe)
	}
	if got := ExtractGitHubURLs(text, false); !reflect.DeepEqual(got, wantRaw) {
		t.Errorf("ExtractGitHubURLs(no-dedupe) = %v; want %v", got, wantRaw)
	}
	// split_links: [text, gh, non_gh, raw]
	srow := g.SplitLinks[0]
	stext, _ := srow[0].(string)
	gh, nonGh, raw := SplitLinks(stext)
	if !reflect.DeepEqual(gh, toStrings(t, srow[1])) || !reflect.DeepEqual(nonGh, toStrings(t, srow[2])) || raw != int(srow[3].(float64)) {
		t.Errorf("SplitLinks drifted: gh=%v non=%v raw=%d; want %v / %v / %v",
			gh, nonGh, raw, srow[1], srow[2], srow[3])
	}
}

// TestGoldenImportGrammar — THE differential: the same corpus through the
// Go parser must equal Python's parse_import_text results byte-for-byte.
func TestGoldenImportGrammar(t *testing.T) {
	g := loadGolden(t)
	corpus, err := os.ReadFile(filepath.Join("testdata", "import_corpus.txt"))
	if err != nil {
		t.Fatalf("read import corpus: %v", err)
	}
	got := ParseImportText(string(corpus))
	if !reflect.DeepEqual(got, g.ParseImportText) {
		gotJSON, _ := json.MarshalIndent(got, "", "  ")
		wantJSON, _ := json.MarshalIndent(g.ParseImportText, "", "  ")
		t.Fatalf("ParseImportText drifted.\n--- want (python) --\n%s\n--- got (go) --\n%s",
			wantJSON, gotJSON)
	}
}

func toStrings(t *testing.T, v any) []string {
	t.Helper()
	raw, ok := v.([]any)
	if !ok {
		t.Fatalf("expected JSON array, got %T (%v)", v, v)
	}
	out := make([]string, len(raw))
	for i, e := range raw {
		s, ok := e.(string)
		if !ok {
			t.Fatalf("expected string element, got %T (%v)", e, e)
		}
		out[i] = s
	}
	return out
}

