func TestSplitLinksPorted(t *testing.T) {
	text := "https://github.com/o/r and https://x.com/post?s=20 and " +
		"https://www.github.com/o2/r2/tree/main read https://reddit.com/x."
	gh, nonGh, raw := SplitLinks(text)
	if !equalSets(gh, []string{"https://github.com/o/r", "https://github.com/o2/r2"}) {
		t.Errorf("github half: %v", gh)
	}
	if !contains(nonGh, "https://x.com/post?s=20") || !contains(nonGh, "https://reddit.com/x") {
		t.Errorf("non-github half (raw form, trailing period stripped): %v", nonGh)
	}
	if raw < 3 {
		t.Errorf("raw count %d", raw)
	}
}

func TestIsGitHubURLPorted(t *testing.T) {
	if !IsGitHubURL("https://github.com/a/b") ||
		!IsGitHubURL("https://www.github.com/a.b/c.d") {
		t.Error("valid GitHub URLs must validate")
	}
	if IsGitHubURL("https://gitlab.com/a/b") || IsGitHubURL("") {
		t.Error("non-GitHub / empty must not validate")
	}
	if IsGitHubURL("https://github.com/../etc/passwd") {
		t.Error("traversal-ish garbage must not validate")
	}
}

