func TestParsePlainAddresses(t *testing.T) {
	r := ParseImportText("https://example.com/one\n" +
		"http://example.com/two\n" +
		"example.com/three\n" +
		"www.example.com/four\n")
	if len(r.GitHubURLs) != 0 {
		t.Errorf("github: %v", r.GitHubURLs)
	}
	want := []string{"https://example.com/one", "http://example.com/two",
		"https://example.com/three", "https://www.example.com/four"}
	if !reflect.DeepEqual(r.WebsiteURLs, want) {
		t.Errorf("websites: %v", r.WebsiteURLs)
	}
	if len(r.Unparsed) != 0 || r.Duplicates != 0 || r.RawCount != 4 {
		t.Errorf("unparsed=%v dups=%d raw=%d", r.Unparsed, r.Duplicates, r.RawCount)
	}
}

