func TestReadImportFileEncodings(t *testing.T) {
	dir := t.TempDir()
	p := filepath.Join(dir, "links.md")

	// UTF-8 BOM stripped
	if err := os.WriteFile(p, []byte("\xef\xbb\xbfhttps://example.com\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	text, err := ReadImportFile(p)
	if err != nil {
		t.Fatal(err)
	}
	r := ParseImportText(text)
	if !reflect.DeepEqual(r.WebsiteURLs, []string{"https://example.com"}) {
		t.Errorf("BOM case: %v", r.WebsiteURLs)
	}

	// latin-1 fallback
	if err := os.WriteFile(p, []byte("https://example.com/caf\xe9\r\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	text, err = ReadImportFile(p)
	if err != nil {
		t.Fatal(err)
	}
	r = ParseImportText(text)
	if len(r.WebsiteURLs) != 1 || !strings.HasPrefix(r.WebsiteURLs[0], "https://example.com/caf") {
		t.Errorf("latin-1 case: %v", r.WebsiteURLs)
	}

	// CRLF file
	if err := os.WriteFile(p, []byte("# heading\r\nhttps://example.com\r\n"), 0o644); err != nil {
		t.Fatal(err)
	}
	text, _ = ReadImportFile(p)
	r = ParseImportText(text)
	if !reflect.DeepEqual(r.WebsiteURLs, []string{"https://example.com"}) {
		t.Errorf("CRLF case: %v", r.WebsiteURLs)
	}
}

func TestDomainOfSchemeLess(t *testing.T) {
	cases := [][2]string{
		{"twitter.com/PyBlog/status/456", "twitter.com"},
		{"www.github.com/o/r", "www.github.com"},
		{"x.com", "x.com"},
		{"", ""},
		{"not a url at all", "not a url at all"},
	}
	for _, c := range cases {
		if got := DomainOf(c[0]); got != c[1] {
			t.Errorf("DomainOf(%q) = %q want %q", c[0], got, c[1])
		}
	}
	if DomainIsBlocked("not a url at all", LawBlockedDomains) {
		t.Error("a host-shaped blob is not on any ban list")
	}
}

func TestDomainIsBlockedSchemeLessLawDomains(t *testing.T) {
	urls := []string{
		"x.com/i/status/1", "twitter.com/a/b", "t.co/xyz",
		"huggingface.co/m", "hf.co/m", "instagram.com/p/x",
		"facebook.com/x", "linkedin.com/in/x",
		"gist.github.com/u/1", "www.github.com/o/r",
	}
	for _, u := range urls {
		if !DomainIsBlocked(u, LawBlockedDomains) {
			t.Errorf("%s must be blocked even without a scheme", u)
		}
	}
}

