func TestSelfDomainsFromConfigPorted(t *testing.T) {
	if !reflect.DeepEqual(SelfDomainsFromConfig(nil), DefaultSelfDomains) {
		t.Error("missing key gives the default")
	}
	if !strings.Contains(SelfDomainsFromConfig(nil)[0], "workers.dev") {
		t.Error("default carries the bot worker host")
	}
	if got := SelfDomainsFromConfig(map[string]any{"web_self_domains": []any{}}); len(got) != 0 {
		t.Errorf("empty list = opt-out, got %v", got)
	}
	if got := SelfDomainsFromConfig(map[string]any{"web_self_domains": ""}); len(got) != 0 {
		t.Errorf("empty string = opt-out, got %v", got)
	}
	got := SelfDomainsFromConfig(map[string]any{"web_self_domains": " A.example , b.example "})
	if !reflect.DeepEqual(got, []string{"a.example", "b.example"}) {
		t.Errorf("comma string: %v", got)
	}
	if !reflect.DeepEqual(SelfDomainsFromConfig(map[string]any{"web_self_domains": 42}), DefaultSelfDomains) {
		t.Error("wrong type falls back to the default")
	}
}

func TestDomainIsSelfPorted(t *testing.T) {
	doms := DefaultSelfDomains
	if !DomainIsSelf("https://github-to-obsidian-bot.aliassadi-plus.workers.dev/auth/?token=abc", doms) {
		t.Error("the bot's own host is self")
	}
	if !DomainIsSelf("https://api.github-to-obsidian-bot.aliassadi-plus.workers.dev/x", doms) {
		t.Error("a subdomain of the bot host is self")
	}
	if DomainIsSelf("https://evil.example/github-to-obsidian-bot.aliassadi-plus.workers.dev", doms) {
		t.Error("the suffix scam must NOT match")
	}
	if DomainIsSelf("https://gist.github.com/x", doms) || DomainIsSelf("https://x.com/1", nil) {
		t.Error("gist/x.com with an empty list must not match")
	}
}

func TestScrubURLTokenPorted(t *testing.T) {
	hex64 := "e8d16400ecb1361ca7b7209a1ab7d485e50451449e6c469ff8e45fdc7a014cb1"
	url := "https://bot.example/auth/?token=" + hex64 + "&next=keep"
	out := ScrubURLToken(url)
	if strings.Contains(out, hex64) {
		t.Error("the secret must be gone")
	}
	if !strings.Contains(out, "token=…") {
		t.Error("the scrub marker must be present")
	}
	if !strings.Contains(out, "next=keep") {
		t.Error("other params untouched")
	}
	if got := ScrubURLToken("https://x.example/?token=abc"); got != "https://x.example/?token=abc" {
		t.Errorf("short values are not secret-shaped: %q", got)
	}
	if got := ScrubURLToken("https://x.example plain"); got != "https://x.example plain" {
		t.Errorf("non-URL text untouched: %q", got)
	}
}

