func TestLawSplitPlatformKeepsGitHubFlowing(t *testing.T) {
	// The wiring the GUI/CLI use: platform law for the repo filter, full
	// law for the websites filter. A github.com repo link is NEVER
	// banned by the platform half…
	repo := "https://github.com/owner/repo"
	if DomainIsBlocked(repo, PlatformDomainsFromConfig(nil)) {
		t.Error("the platform law must never blanket-ban github.com repo links")
	}
	// …while the full law refuses it at the websites layer, together
	// with gists.
	if !DomainIsBlocked(repo, BlockedDomainsFromConfig(nil)) {
		t.Error("the full law bans github.com at the websites layer")
	}
	if !DomainIsBlocked("https://gist.github.com/o/abc123", BlockedDomainsFromConfig(nil)) ||
		!DomainIsBlocked("https://x.com/1", BlockedDomainsFromConfig(nil)) {
		t.Error("gists and x.com are blocked at the websites layer")
	}
	if DomainIsBlocked("https://example.com/x", BlockedDomainsFromConfig(nil)) {
		t.Error("an ordinary site flows")
	}
}

func equalSets(a, b []string) bool {
	if len(a) != len(b) {
		return false
	}
	seen := map[string]int{}
	for _, s := range a {
		seen[s]++
	}
	for _, s := range b {
		if seen[s] == 0 {
			return false
		}
		seen[s]--
	}
	return true
}
